    cout << "Enter a category from 1 through 10: ";
    cin >> choice;
    switch (choice) {
        case 10: result = "special";
        case 9: result = "alternate"; break;
        default: result = "standard";
    }
    cout << "Assigned service desk: " << result << "\n";
    cout << "Selection processed.\n";
    cout << "Category checked: " << choice << "\n";
