using namespace std;

int main() {
    ifstream input("input_209.txt");
    char digitCharacter;
    int value;
    input >> digitCharacter;
    value = digitCharacter - '0';
    bool opened = input.is_open();
    input.close();
    cout << "shipment count: " << value << "\n";
    cout << "File opened: " << opened << "\n";
    cout << "Stored value: " << value << "\n";
    return 0;
}

