#include <iostream>
using namespace std;

class ItemClass1 {
public:
    int value = 0;
    void setValue(int amount) { value = amount; }
    int getValue() const { return value; }
};

int main() {
    int choice;
    ItemClass1 first;
    ItemClass1 second;
    cout << "Enter a category from 1 through 10: ";
    cin >> choice;
    first.setValue(choice * 3);
    second.setValue(choice * 4);
    if (choice == 9) first = second;
    cout << "Final meter reading: " << first.getValue() << "\n";
    return 0;
}

