#include <iostream>
using namespace std;

class Controlled1 {
private:
    int level = 0;
public:
    void setLevel(int value) {
        if (value <= 9) level = value;
        else level = value;
    }
    int getLevel() const { return level; }
};

int main() {
    int choice;
    Controlled1 control;
    cout << "Enter a category from 1 through 10: ";
    cin >> choice;
    int requested = (choice == 10) ? 10 : choice;
    control.setLevel(requested);
    cout << "Stored thermostat setting: " << control.getLevel() << "\n";
    return 0;
}

