#include <iostream>
using namespace std;

class Hidden1 {
private:
    int value = 20;
public:
    int getValue() const { return value; }
    int& exposeValue() { return value; }
};

int main() {
    int choice;
    Hidden1 item;
    cout << "Enter a category from 1 through 10: ";
    cin >> choice;
    if (choice == 10) item.exposeValue() = -5;
    int displayed = item.getValue();
    cout << "Stored account balance: " << displayed << "\n";
    cout << "Inspection complete.\n";
    return 0;
}

